#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Stripe go-live for Toowix billing. Run ON THE PRODUCTION SERVER as root:
#   sudo bash deploy/stripe-go-live.sh
# GST is not covered here (waiting on the accountant).

DEPLOY_DIR="${DEPLOY_DIR:-/root/toowix-mail-platform/deploy}"
# The library defaults ENV_FILE to ./.env; production compose reads .env.production.
ENV_FILE="${GOLIVE_ENV_FILE:-$DEPLOY_DIR/.env.production}"
compose() { docker compose -p deploy --project-directory "$DEPLOY_DIR" --env-file "$ENV_FILE" -f "$DEPLOY_DIR/docker-compose.prod.yml" "$@"; }
WEBHOOK_EVENTS=(
  checkout.session.completed invoice.payment_succeeded invoice.payment_failed invoice.payment_action_required
  customer.subscription.updated customer.subscription.deleted customer.subscription.trial_will_end
  charge.refunded charge.dispute.created credit_note.created
)

run_wizard() {

TOTAL_STAGES=10

banner "Toowix: Stripe go-live"
[[ -f "$ENV_FILE" ]] || { warn "No $ENV_FILE. Run this on the production server (or set ENV_FILE=...)."; exit 1; }

stage "Stripe account is ready for live payments in India"
say "Live charges only work once Stripe has activated the account for INR recurring card payments."
open_url "https://dashboard.stripe.com/account/onboarding"
step "Finish any 'Activate payments' steps (business details, bank account, KYC)."
step "Check the account can take recurring Indian card payments (RBI e-mandates). If unsure, ask Stripe support."
note "Indian cards need a mandate for automatic charges; charges over ₹15,000 need approval each time."
confirm "Is the live account activated for recurring INR card payments?" || { warn "Come back once Stripe has activated it."; exit 1; }

stage "Roll the leaked test keys"
say "Two sets of test keys appeared in chat transcripts. Rolling makes the old ones useless."
open_url "https://dashboard.stripe.com/test/apikeys"
step "Toowix test account (acct_1UABmN6zGY5UFhgB): Secret key row → ⋯ → Roll key → expire now."
step "Put the new test secret key in backend/.env on developer machines (STRIPE_SECRET_KEY)."
step "Ask the sendbycloud project's owner to roll their keys too (pasted in chat on 2026-10-21)."
pause

stage "Live API keys"
open_url "https://dashboard.stripe.com/apikeys"
step "Make sure the Dashboard is in LIVE mode (test-mode toggle off)."
step "Copy the Publishable key (starts pk_live_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the live publishable key:"
[[ "$STRIPE_PUBLISHABLE_KEY" == pk_live_* ]] || { warn "That isn't a pk_live_ key."; exit 1; }
step "Secret key row → Reveal live key → copy (starts sk_live_ or rk_live_)."
ask_secret STRIPE_SECRET_KEY "Paste the live secret key:"
[[ "$STRIPE_SECRET_KEY" == sk_live_* || "$STRIPE_SECRET_KEY" == rk_live_* ]] || { warn "That isn't a live secret key."; exit 1; }
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
# docker-compose.prod.yml defaults this to false, which switches billing off even with keys set.
write_env ENABLE_BILLING "true"

stage "Live webhook endpoint"
say "Stripe tells the backend about payments through this endpoint."
ask BACKEND_PUBLIC_URL "Public backend URL (e.g. https://api.toowix.com):"
BACKEND_PUBLIC_URL="${BACKEND_PUBLIC_URL%/}"
WEBHOOK_URL="$BACKEND_PUBLIC_URL/api/webhooks/stripe"
existing=$(curl -fsS "https://api.stripe.com/v1/webhook_endpoints?limit=100" -u "$STRIPE_SECRET_KEY:" | grep -c "\"url\": \"$WEBHOOK_URL\"" || true)
if (( existing > 0 )); then
  warn "An endpoint for $WEBHOOK_URL already exists. Stripe only shows its signing secret in the Dashboard."
  open_url "https://dashboard.stripe.com/webhooks"
  step "Open that endpoint → check it listens to: ${WEBHOOK_EVENTS[*]}"
  step "Signing secret → Reveal → copy (starts whsec_)."
  ask_secret STRIPE_WEBHOOK_SECRET "Paste the signing secret:"
else
  say "This creates $WEBHOOK_URL in your live Stripe account, listening to:"
  note "${WEBHOOK_EVENTS[*]}"
  confirm "Create it now?" || { warn "Not created. Re-run when ready."; exit 1; }
  args=(-d "url=$WEBHOOK_URL" -d "description=Toowix billing")
  for e in "${WEBHOOK_EVENTS[@]}"; do args+=(-d "enabled_events[]=$e"); done
  response=$(curl -fsS https://api.stripe.com/v1/webhook_endpoints -u "$STRIPE_SECRET_KEY:" "${args[@]}")
  STRIPE_WEBHOOK_SECRET=$(printf '%s' "$response" | sed -n 's/.*"secret": *"\(whsec_[^"]*\)".*/\1/p')
  [[ -n "$STRIPE_WEBHOOK_SECRET" ]] || { warn "Stripe didn't return a signing secret. Check the Dashboard → Webhooks."; exit 1; }
fi
[[ "$STRIPE_WEBHOOK_SECRET" == whsec_* ]] || { warn "That isn't a whsec_ secret."; exit 1; }
write_env STRIPE_WEBHOOK_SECRET "$STRIPE_WEBHOOK_SECRET"

stage "Receipt emails"
say "Stripe emails the customer a receipt (with the invoice PDF) after every successful payment."
open_url "https://dashboard.stripe.com/settings/emails"
step "Customer emails: turn on 'Successful payments' and 'Refunds'."
step "Check the business name, logo and support email shown on receipts (Settings → Business → Public details)."
pause

stage "Alerts when webhooks fail"
say "If the backend stops accepting webhooks, payments stop reaching the app. You want to hear about it."
open_url "https://dashboard.stripe.com/settings/user"
step "Under your email notification preferences, turn on alerts for failed webhooks (and disputes)."
note "If the setting isn't there, Stripe's Webhooks page lists failing deliveries; check it after launch."
pause

stage "Production database has no test-mode Stripe data"
say "Customer and price IDs from test mode don't exist in live mode and would break billing."
counts=$(compose exec -T mongodb mongosh --quiet toowix_mail --eval '
  print("tenants with a Stripe customer: " + db.tenants.countDocuments({ stripeCustomerId: { $ne: null } }));
  print("plans with a cached Stripe price: " + db.plans.countDocuments({ stripePriceId: { $ne: null } }));
  print("billed domain rows: " + db.domain_subscriptions.countDocuments({ stripeSubscriptionId: /^sub_(?!trial_)/ }));
  print("sandbox domain rows (billing was off): " + db.domain_subscriptions.countDocuments({ stripeSubscriptionId: /^sub_trial_/ }));
') || { warn "Couldn't query Mongo through docker compose."; counts=""; }
printf '%s\n' "$counts" | sed 's/^/    /'
if printf '%s' "$counts" | grep -qE '(customer|price|billed domain rows): [1-9]'; then
  warn "Stripe IDs are present. If they came from test mode, clear them before going live."
  warn "Don't continue until someone has checked them."
  confirm "Have they been checked (or cleared)?" || exit 1
fi
if printf '%s' "$counts" | grep -qE 'sandbox[^:]*: [1-9]'; then
  warn "Existing Tenants were set up while billing was off. Decide how they move onto paid billing before launch."
  confirm "Continue anyway?" || exit 1
fi

stage "Backups"
say "From now on the database holds who has paid. Losing it means losing billing state."
step "Confirm production Mongo is backed up daily, off the server, and that a restore has been tried once."
note "The backend has BACKUP_ENCRYPTION_KEY / AWS_S3_BUCKET settings; check they are set if you use them."
confirm "Are backups in place?" || warn "Set them up soon after launch."

stage "Restart the backend and check the webhook"
confirm "Restart the backend now so it reads the new settings?" || { warn "Restart later: docker compose ... up -d backend"; exit 1; }
compose up -d backend
step "Waiting for the backend to come up..."
sleep 20
code=$(curl -s -o /dev/null -w '%{http_code}' -X POST "$WEBHOOK_URL" -H 'Content-Type: application/json' --data-raw '{}' || true)
case "$code" in
  400) say "${GREEN}✓${RESET} Webhook answers 400 to an unsigned request: the signing secret is loaded." ;;
  503) warn "503: the backend has no webhook secret. Check STRIPE_WEBHOOK_SECRET in $ENV_FILE."; exit 1 ;;
  *)   warn "Unexpected $code from $WEBHOOK_URL. Check the backend logs: docker logs toowix-prod-backend"; exit 1 ;;
esac
open_url "https://dashboard.stripe.com/webhooks"
step "Optional: on the endpoint, 'Send test event' → checkout.session.completed should show 200."
pause

stage "One real payment with a real Indian card"
say "Prove the whole path with real money, then give it back."
step "1. Register a throwaway organisation in the tenant admin, add a domain on Starter, create a mailbox."
step "2. Ready for checkout → pay with a real Indian card (the bank may ask for an OTP)."
step "3. Billing page: the Trial shows 60 days. Nothing is charged during the Trial."
step "4. To see a real charge without waiting 60 days: Stripe Dashboard → that customer's subscription → end the trial now."
step "5. Billing page → Change plan → Pro: the difference is charged at once; approve the OTP if asked."
step "6. Stripe Dashboard → Payments: refund both charges. Then Billing page → Cancel subscription."
step "7. Check a receipt email arrived, and the Stripe Webhooks page shows only 200s."
pause

finish
}

run_wizard "$@"; exit
